import{_ as t,o as e,c as l,ag as r}from"./chunks/framework.CvZZEx4j.js";const u=JSON.parse('{"title":"对话与文本","description":"","frontmatter":{},"headers":[],"relativePath":"basics/dialogue.md","filePath":"basics/dialogue.md","lastUpdated":null}'),o={name:"basics/dialogue.md"};function i(s,a,d,n,h,c){return e(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="对话与文本" tabindex="-1">对话与文本 <a class="header-anchor" href="#对话与文本" aria-label="Permalink to &quot;对话与文本&quot;">​</a></h1><h2 id="ai-输出如何变成-galgame-格式" tabindex="-1">AI 输出如何变成 Galgame 格式 <a class="header-anchor" href="#ai-输出如何变成-galgame-格式" aria-label="Permalink to &quot;AI 输出如何变成 Galgame 格式&quot;">​</a></h2><p>当插件启用并注入了 COT 世界书后，AI 会按照特定的标签格式输出内容。插件的解析器会自动将这些标签渲染为 Galgame 界面元素。</p><p>你不需要关心标签的具体语法——只需注入世界书，AI 就会自动输出正确的格式。</p><h2 id="逐段推进对话" tabindex="-1">逐段推进对话 <a class="header-anchor" href="#逐段推进对话" aria-label="Permalink to &quot;逐段推进对话&quot;">​</a></h2><p>AI 的每条回复可能包含多段对话。插件会将它们分段展示：</p><ol><li>第一段对话自动显示</li><li>点击覆盖层空白区域或「下一步」按钮，显示下一段</li><li>直到所有段落展示完毕</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>你也可以快速点击跳过动画，直接显示当前段落的完整文本。</p></div><h2 id="角色对话与旁白" tabindex="-1">角色对话与旁白 <a class="header-anchor" href="#角色对话与旁白" aria-label="Permalink to &quot;角色对话与旁白&quot;">​</a></h2><p>插件会区分两种文本类型：</p><ul><li><strong>角色对话</strong>：显示角色名 + 带引号的对话，并附带表情变化</li><li><strong>旁白</strong>：直接显示描述性文本，不带角色名</li></ul><h2 id="文字特效" tabindex="-1">文字特效 <a class="header-anchor" href="#文字特效" aria-label="Permalink to &quot;文字特效&quot;">​</a></h2><p>在设置面板中，你可以选择不同的文字显示特效：</p><table tabindex="0"><thead><tr><th>特效</th><th>说明</th></tr></thead><tbody><tr><td><strong>无</strong></td><td>文字直接显示</td></tr><tr><td><strong>打字机</strong></td><td>文字逐字显示，模拟打字效果</td></tr><tr><td><strong>淡入</strong></td><td>文字以淡入动画显示</td></tr></tbody></table><h2 id="字号与透明度" tabindex="-1">字号与透明度 <a class="header-anchor" href="#字号与透明度" aria-label="Permalink to &quot;字号与透明度&quot;">​</a></h2><p>在设置面板的「显示设置」中可以调节：</p><ul><li><strong>字号大小</strong>：调整对话文字的大小</li><li><strong>对话框透明度</strong>：调整对话框背景的透明程度</li></ul>',17)])])}const g=t(o,[["render",i]]);export{u as __pageData,g as default};
